import math
from typing import Any, Dict, List, Optional, Tuple
from skyguard.data.schema import StationMetadata
from skyguard.dacm.geometry import haversine_distance_km


def calculate_compass_bearing(lat1: float, lon1: float, lat2: float, lon2: float) -> Tuple[float, str]:
    """Calculates forward azimuth bearing in degrees (0-360) and 8-point compass direction."""
    phi1, phi2 = math.radians(lat1), math.radians(lat2)
    delta_lambda = math.radians(lon2 - lon1)
    y = math.sin(delta_lambda) * math.cos(phi2)
    x = math.cos(phi1) * math.sin(phi2) - math.sin(phi1) * math.cos(phi2) * math.cos(delta_lambda)
    bearing = (math.degrees(math.atan2(y, x)) + 360.0) % 360.0

    dirs = ["N", "NE", "E", "SE", "S", "SW", "W", "NW", "N"]
    idx = int((bearing + 22.5) // 45)
    return round(bearing, 1), dirs[idx]


