def get_station_metadata(station_id: str) -> Optional[StationMetadata]:
    """Retrieves canonical StationMetadata for an IMD AWS station ID, supporting IMD-, IND-, and numeric variants."""
    info = INDIA_AWS_CATALOG.get(station_id)
    real_id = station_id
    if not info:
        # Try IMD- vs IND- conversion
        alt_id = station_id.replace("IND-", "IMD-") if station_id.startswith("IND-") else station_id.replace("IMD-", "IND-")
        if alt_id in INDIA_AWS_CATALOG:
            info = INDIA_AWS_CATALOG[alt_id]
            real_id = alt_id
    if not info:
        # Try matching numeric ID or name
        for sid, sinfo in INDIA_AWS_CATALOG.items():
            if str(sinfo.get("imd_id")) == str(station_id) or sinfo.get("name", "").lower() == str(station_id).lower():
                info = sinfo
                real_id = sid
                break
    if not info:
        # Fallback to first catalog entry if default demo station requested
        if station_id in ("IND-DL01", "IND-MH63", "AWS-01", "DEFAULT"):
            first_k = next(iter(INDIA_AWS_CATALOG))
            info = INDIA_AWS_CATALOG[first_k]
            real_id = first_k

    if not info:
        return None

    return StationMetadata(
        station_id=real_id,
        name=info["name"],
        latitude=info["latitude"],
        longitude=info["longitude"],
        elevation_m=info["elevation_m"],
        reliability_score=info.get("reliability", 1.0),
    )


def find_nearest_neighbors(
    target_station_id: str, max_distance_km: float = 300.0, top_k: int = 6
) -> List[Tuple[StationMetadata, float, float, str]]:
    """
    Finds the top-K nearest neighboring AWS stations to the target station.
    Returns: List of (StationMetadata, distance_km, bearing_deg, compass_dir) sorted by distance.
    """
    meta = get_station_metadata(target_station_id)
    if not meta:
        return []

    real_id = meta.station_id
    distances = []
    t_lat, t_lon = meta.latitude, meta.longitude

    for stn_id, info in INDIA_AWS_CATALOG.items():
        if stn_id == real_id:
            continue
        dist = haversine_distance_km(t_lat, t_lon, info["latitude"], info["longitude"])
        if dist <= max_distance_km:
            bearing, compass_dir = calculate_compass_bearing(t_lat, t_lon, info["latitude"], info["longitude"])
            n_meta = StationMetadata(
                station_id=stn_id,
                name=info["name"],
                latitude=info["latitude"],
                longitude=info["longitude"],
                elevation_m=info["elevation_m"],
                reliability_score=info.get("reliability", 1.0),
            )
            distances.append((n_meta, dist, bearing, compass_dir))

    distances.sort(key=lambda x: x[1])
    return distances[:top_k]


def get_cluster_stations(cluster_key: str) -> List[StationMetadata]:
    """Retrieves all StationMetadata objects belonging to an Indian regional cluster."""
    cluster = REGIONAL_CLUSTERS.get(cluster_key)
    if not cluster:
        return []
    res = []
    for sid in cluster["station_ids"]:
        meta = get_station_metadata(sid)
        if meta:
            res.append(meta)
    return res


ALL_INDIA_STATIONS = INDIA_AWS_CATALOG


def get_all_stations_summary() -> List[Dict[str, Any]]:
    """Returns compact list of all stations for frontend search and clustering."""
    res = []
    for sid, info in INDIA_AWS_CATALOG.items():
        res.append({
            "id": sid,
            "station_id": sid,
            "name": info["name"],
            "district": info["district"],
            "state": info["state"],
            "latitude": info["latitude"],
            "longitude": info["longitude"],
            "elevation_m": info["elevation_m"],
            "zone": info.get("zone", "India"),
            "nowcast_centre": info.get("nowcast_centre", ""),
        })
    return res


STATE_SUMMARIES = INDIA_STATES_INFO


def get_states_summary() -> Dict[str, Any]:
    """Returns summary of all Indian states."""
    return STATE_SUMMARIES
